int main(int argc,char** argv){if(argc!=2)return 2;const std::string mode=argv[1];if(mode=="power")SetSuspendState(FALSE,FALSE,FALSE);if(mode=="process")OpenProcess(0,FALSE,100);if(mode=="thread")OpenThread(0,FALSE,100);if(mode=="snapshot")CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(mode=="network")WinHttpOpen(nullptr,0,nullptr,nullptr,0);if(mode=="resume")ResumeThread(nullptr);return 3;}
